const toggle=document.querySelector('.menu-toggle');
const navigation=document.querySelector('#navigation');
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close menu':'Open menu');navigation.classList.toggle('open',open)});
navigation.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{navigation.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu')}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){navigation.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.focus()}});
if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el))}
document.querySelectorAll('[data-program]').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#goal').value=button.dataset.program;if(button.dataset.program==='Online coaching')document.querySelector('input[name="format"][value="Online"]').checked=true;document.querySelector('#get-started').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelector('#name').focus({preventScroll:true})}));
const dialog=document.querySelector('#briefing-dialog');const output=document.querySelector('#briefing-output');const status=document.querySelector('#copy-status');
document.querySelector('#briefing-form').addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget);const name=String(form.get('name')).trim();if(!name){document.querySelector('#name').setCustomValidity('Please enter your name.');document.querySelector('#name').reportValidity();return}output.value=`Hi! My name is ${name}.\n\nI’d like to learn more about APEX coaching.\nMy goal: ${form.get('goal')}.\nPreferred format: ${form.get('format')}.\n\nCould we discuss availability, an initial assessment, and pricing?`;status.textContent='';dialog.showModal()});
document.querySelector('#name').addEventListener('input',event=>event.target.setCustomValidity(''));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
document.querySelector('#copy-briefing').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(output.value);status.textContent='Brief copied! Share it with the trainer once their contact details are available.'}catch{output.focus();output.select();status.textContent='Select and copy your brief with Ctrl+C or your device’s copy menu.'}});
document.querySelector('#year').textContent=new Date().getFullYear();
